def check_retry(script, max_attempts, base_delay_ms, max_delay_ms):
    calls = 0
    delays = []

    def action():
        nonlocal calls
        step = script[calls]
        calls += 1
        if step == "timeout":
            raise TimeoutError("no reply")
        if step == "fail":
            raise ValueError("bad request")
        return int(step)

    try:
        outcome = str(retry(action, max_attempts, base_delay_ms, max_delay_ms, delays.append))
    except TimeoutError:
        outcome = "gave up"
    except ValueError:
        outcome = "failed"
    return [outcome, calls, delays]

