public static class RetryCheck
{
    public static List<object> Check(string[] script, int maxAttempts, int baseDelayMs, int maxDelayMs)
    {
        int calls = 0;
        var delays = new List<int>();
        string outcome;
        try
        {
            int result = Solution.Retry(() =>
            {
                string next = script[calls++];
                if (next == "timeout") throw new TimeoutException("no reply");
                if (next == "fail") throw new InvalidOperationException("bad request");
                return int.Parse(next);
            }, maxAttempts, baseDelayMs, maxDelayMs, delays.Add);
            outcome = result.ToString();
        }
        catch (TimeoutException) { outcome = "gave up"; }
        catch (InvalidOperationException) { outcome = "failed"; }
        return [outcome, calls, delays];
    }
}

